(() => {
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics=CURRICULUM.topics;const questions=topics.flatMap((t,ti)=>t.resources.map((q,qi)=>({...q,ti,qi})));const byId=new Map(questions.map(q=>[q.id,q]));let labs=[],heroIndex=0,lang='cpp',filter={query:'',difficulty:'All',topic:'All',status:'All'};
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const progress=read('dsa-motion-progress',{}),bookmarks=read('dsa-motion-bookmarks',{}),notes=read('dsa-motion-notes',{});function save(key,v){try{localStorage.setItem(key,JSON.stringify(v))}catch{toast('Browser storage is unavailable. Changes last for this visit.')}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
function topicName(i){return TOPICS[i].title}function doneCount(i){return questions.filter(q=>(i===undefined||q.ti===i)&&progress[q.id]).length}function progressHTML(){let n=doneCount();return `<div class="progress-row"><span>${n} / 165 understood</span><span class="progress-track"><i style="width:${n/165*100}%"></i></span><small>Saved on this browser</small></div>`}
function qrow(q){return `<div class="qrow"><button data-complete="${q.id}" class="${progress[q.id]?'completed':''}" aria-label="${progress[q.id]?'Mark incomplete':'Mark understood'}: ${esc(q.name)}" aria-pressed="${!!progress[q.id]}">${progress[q.id]?'☑':'□'}</button><a href="#question/${q.id}">${esc(q.name)} <small>↗</small></a><span class="difficulty ${q.level}">${q.level}</span><button data-bookmark="${q.id}" class="${bookmarks[q.id]?'bookmarked':''}" aria-label="${bookmarks[q.id]?'Remove bookmark':'Bookmark'}: ${esc(q.name)}" aria-pressed="${!!bookmarks[q.id]}">${bookmarks[q.id]?'★':'☆'}</button></div>`}
function attachRows(){document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{let id=b.dataset.complete;progress[id]=!progress[id];save('dsa-motion-progress',progress);b.classList.toggle('completed',progress[id]);b.textContent=progress[id]?'☑':'□';b.setAttribute('aria-pressed',!!progress[id]);b.setAttribute('aria-label',`${progress[id]?'Mark incomplete':'Mark understood'}: ${byId.get(id).name}`);if(location.hash.startsWith('#questions')){const y=scrollY;renderSheet(false);scrollTo(0,y)}toast(progress[id]?'Marked understood':'Marked incomplete')});document.querySelectorAll('[data-bookmark]').forEach(b=>b.onclick=()=>{let id=b.dataset.bookmark;bookmarks[id]=!bookmarks[id];save('dsa-motion-bookmarks',bookmarks);b.classList.toggle('bookmarked',bookmarks[id]);b.textContent=bookmarks[id]?'★':'☆';b.setAttribute('aria-pressed',!!bookmarks[id]);b.setAttribute('aria-label',`${bookmarks[id]?'Remove bookmark':'Bookmark'}: ${byId.get(id).name}`);if(location.hash.startsWith('#questions')&&filter.status==='Bookmarked'){let y=scrollY;renderSheet(false);scrollTo(0,y)}toast(bookmarks[id]?'Bookmarked':'Bookmark removed')})}
function mini(i){return `<div class="mini-bars" aria-hidden="true">${Array.from({length:9},(_,j)=>`<i style="height:${8+((i*7+j*11)%27)}px;${j===4?'opacity:1':''}"></i>`).join('')}</div>`}
function cards(){return topics.map((t,i)=>`<a href="#topic/${i}" class="topic-card"><div class="top"><span>Topic ${String(i+1).padStart(2,'0')}</span><span>${t.resources.length} questions</span></div>${mini(i)}<h3>${topicName(i)}</h3><p>${TOPICS[i].short}</p><div class="bottom"><span>${doneCount(i)?`${doneCount(i)} understood`:'Explore the idea & model'}</span><span>↗</span></div></a>`).join('')}
function home(){document.title='DSA in Motion — See the algorithm.';$('#main').innerHTML=`<section class="hero"><div class="hero-inner"><div class="hero-copy"><div class="tag"><b>3D</b> Algorithms you can turn, change, and understand</div><h1>Learn DSA<br><em>in motion.</em></h1><p>Stop memorizing solutions. See why they work.<br>From your first array to graphs and dynamic programming, build intuition one interactive model at a time.</p><div class="actions"><a class="btn primary" href="#topic/0">Start learning <span>↗</span></a><a class="textlink" href="#questions">Explore the question sheet</a></div><div class="source-note"><span class="line"></span>Following the <a href="https://namastedev.com/namaste-dsa-sheet" target="_blank" rel="noopener">Namaste DSA Sheet ↗</a><span>·</span> C++ / JS / Python</div></div><div class="hero-model"><div class="model-card"><div class="model-top"><span id="hero-label"></span><div class="live">Interactive model</div></div><div id="hero-lab"></div><div class="model-description"><h3 id="hero-name"></h3><p id="hero-description"></p></div></div><div class="hero-model-bottom"><span id="hero-counter"></span><div class="dots" aria-label="Choose a model"></div><div class="arrowbuttons"><button id="hero-prev" aria-label="Previous model">←</button><button id="hero-next" aria-label="Next model">→</button></div></div></div></div></section><div class="stats"><div class="stat"><strong>165</strong><span>Questions to work through</span></div><div class="stat"><strong>14</strong><span>Topics, from first principles</span></div><div class="stat"><strong>13</strong><span>Interactive pattern labs</span></div><div class="stat"><strong>3</strong><span>Languages for every solution</span></div></div><section class="wrap section"><div class="section-head"><div><div class="eyebrow">The learning path</div><h2>From “I’ve seen this”<br>to “I understand this.”</h2></div><p>Follow the sheet in order, or jump to the idea you’re stuck on. Each topic connects an explanation, a working model, and practice.</p></div><div class="topic-grid">${cards()}</div></section><section class="rhythm"><div class="wrap section"><div class="eyebrow">A better way to practice</div><h2>See it. Move it. Code it.</h2><div class="steps-grid"><div><b>01 / Understand</b><h3>Find the invariant.</h3><p>Learn what stays true at every step. That is the reason an algorithm works.</p></div><div><b>02 / Experiment</b><h3>Make the model move.</h3><p>Change an input, follow the pointers, and replay the moment an idea clicks.</p></div><div><b>03 / Implement</b><h3>Read it in your language.</h3><p>Original C++, JavaScript, and Python solutions, with time and space analysis.</p></div><div><b>04 / Remember</b><h3>Keep your own trail.</h3><p>Bookmark hard questions, save notes, and track understanding on this browser.</p></div></div></div></section><div class="wrap"><div class="cta-band"><div><h2>Your first “aha” is one model away.</h2><p>No account needed. Pick a topic and start moving things.</p></div><a class="btn primary" href="#lab">Open the playground <span>↗</span></a></div></div>`;showHero();$('#hero-prev').onclick=()=>{heroIndex=(heroIndex+5)%6;showHero()};$('#hero-next').onclick=()=>{heroIndex=(heroIndex+1)%6;showHero()}}
function showHero(){if(labs.length)labs.forEach(l=>l.destroy());labs=[];let ids=['water','binary','tree','linked','dp','graph'],id=ids[heroIndex],x=LABS[id];$('#hero-label').textContent=`Topic ${String(x.topic+1).padStart(2,'0')} / ${topicName(x.topic)}`;$('#hero-name').textContent=x.title;$('#hero-description').textContent=x.description;$('#hero-counter').textContent=`0${heroIndex+1} / 06`;$('.dots').innerHTML=ids.map((_,i)=>`<button aria-label="Show ${LABS[ids[i]].title}" class="${i===heroIndex?'active':''}" data-model="${i}"></button>`).join('');document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{heroIndex=+b.dataset.model;showHero()});let l=new AlgorithmLab($('#hero-lab'),id,true);l.index=id==='water'?8:id==='tree'?4:Math.min(2,l.states.length-1);l.draw();labs.push(l)}
function learn(){document.title='Learning path — DSA in Motion';$('#main').innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">Your curriculum</div><h1>One idea at a time.</h1><p>Fourteen topics, in the order of the Namaste DSA Sheet. Start with the explanation, experiment in the pattern lab, then test yourself on the questions.</p>${progressHTML()}</div><div class="topic-grid">${cards()}</div><div class="cta-band"><p>Already know the concepts? Go straight to practice.</p><a class="btn" href="#questions">Open the question sheet ↗</a></div></div>`}
function renderSheet(initial=true){document.title='Question sheet — DSA in Motion';if(initial)$('#main').innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">The Namaste DSA Sheet, visualized</div><h1>Practice with a picture.</h1><p>All 165 questions, with original explanations and solutions in three languages. Use a topic’s pattern lab to build intuition, then solve the exact problem.</p><div id="sheet-progress">${progressHTML()}</div></div><div class="filters"><input id="search" aria-label="Search questions" placeholder="Search questions or companies…" value="${esc(filter.query)}"><select id="difficulty" aria-label="Filter difficulty"><option>All</option><option>Easy</option><option>Medium</option><option>Hard</option></select><select id="topic-filter" aria-label="Filter topic"><option value="All">All topics</option>${TOPICS.map((t,i)=>`<option value="${i}">${t.title}</option>`).join('')}</select>${['All','Bookmarked','Completed'].map(s=>`<button data-status="${s}" class="${filter.status===s?'selected':''}">${s}</button>`).join('')}</div><p id="result-count" style="color:var(--muted);font-size:12px"></p><div id="sheet-results"></div><div class="source-panel">Question names, topic order, difficulty labels, and source links: <a href="https://namastedev.com/namaste-dsa-sheet" target="_blank" rel="noopener">Namaste DSA Sheet ↗</a>. Explanations and solutions are independently written.</div><div style="height:50px"></div></div>`;const matching=questions.filter(q=>(filter.difficulty==='All'||q.level===filter.difficulty)&&(filter.topic==='All'||q.ti===+filter.topic)&&(filter.status==='All'||filter.status==='Bookmarked'&&bookmarks[q.id]||filter.status==='Completed'&&progress[q.id])&&`${q.name} ${q.companies.join(' ')} ${topicName(q.ti)}`.toLowerCase().includes(filter.query.toLowerCase()));$('#sheet-results').innerHTML=topics.map((t,i)=>{const qs=matching.filter(q=>q.ti===i);return qs.length?`<details class="sheet-group" open><summary><span>${String(i+1).padStart(2,'0')} &nbsp; ${topicName(i)}</span><small>${doneCount(i)} / ${t.resources.length} &nbsp;⌄</small></summary>${qs.map(qrow).join('')}</details>`:''}).join('')||'<div class="empty">No questions match these filters. Clear the search or choose another topic.</div>';$('#result-count').textContent=`${matching.length} question${matching.length===1?'':'s'} shown`;$('#sheet-progress').innerHTML=progressHTML();attachRows();if(initial){$('#difficulty').value=filter.difficulty;$('#topic-filter').value=filter.topic;$('#search').oninput=e=>{filter.query=e.target.value;renderSheet(false)};$('#difficulty').onchange=e=>{filter.difficulty=e.target.value;renderSheet(false)};$('#topic-filter').onchange=e=>{filter.topic=e.target.value;renderSheet(false)};document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{filter.status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('selected',x===b));renderSheet(false)})}}
function sidebar(i){return `<aside class="sidebar"><div class="sidebar-inner"><h3>The learning path</h3>${TOPICS.map((t,j)=>`<a href="#topic/${j}" class="${i===j?'active':''}"><span>${String(j+1).padStart(2,'0')}</span>${t.title}</a>`).join('')}<a href="#questions">↗ All 165 questions</a></div></aside>`}
function topicPage(i){if(!TOPICS[i]){location.hash='#learn';return}let t=TOPICS[i];document.title=`${t.title} — DSA in Motion`;$('#main').innerHTML=`<div class="study">${sidebar(i)}<article class="lesson"><div class="breadcrumbs"><a href="#learn">Learning path</a> / Topic ${String(i+1).padStart(2,'0')}</div><div class="tag"><b>${topics[i].resources.length}</b> questions · 3 languages</div><h1>${t.title}</h1><p class="lead">${t.idea}</p><div class="insight"><b>The invariant</b>${t.invariant}</div><h2>Move the idea around.</h2><p>${LABS[t.lab].description}</p><div class="lab" id="topic-lab"></div><h2>Why it works</h2><ol>${t.explain.map(s=>`<li>${s}</li>`).join('')}</ol><div class="insight"><b>A mistake to watch for</b>${t.pitfall}</div><h2>Check your intuition</h2><div class="quiz"><p>${t.quiz}</p><div class="options">${t.options.map((s,j)=>`<button data-answer="${j}">${s}</button>`).join('')}</div><p class="feedback" aria-live="polite"></p></div><h2>Put it into practice</h2><p>Each question has an explanation, complexity analysis, and a solution in C++, JavaScript, and Python.</p><div class="sheet-group lesson-list">${questions.filter(q=>q.ti===i).map(qrow).join('')}</div><div class="end-nav">${i?`<a href="#topic/${i-1}">← ${topicName(i-1)}</a>`:'<a href="#learn">← Learning path</a>'}${i<13?`<a href="#topic/${i+1}">${topicName(i+1)} →</a>`:'<a href="#questions">All questions →</a>'}</div></article></div>`;labs.push(new AlgorithmLab($('#topic-lab'),t.lab));attachRows();document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const ok=+b.dataset.answer===t.answer;$('.feedback').textContent=ok?`Exactly. ${t.why}`:`Try again. ${t.options[+b.dataset.answer]} does not fit the invariant.`;$('.quiz').classList.toggle('correct',ok)})}
const exactLabs={'Trapping Rain Water':'water','Binary Search':'binary','Reverse Linked List':'linked','Longest Substring Without Repeating Characters':'window','Valid Parentheses':'stack','Climbing Stairs':'dp','Level Order Traversal':'tree','Search in a BST':'bst','Subsets - The Power Set':'subsets'};
function codeMarkup(code){return esc(code).split('\n').map(l=>{if(/^\s*(\/\/|#(?!include)|\/\*|\*)/.test(l))return `<span class="comment">${l}</span>`;return l.replace(/\b(class|def|return|if|else|elif|for|while|in|const|let|function|int|void|bool|auto|public|static|None|null|True|False|true|false|new|from|import|using|namespace|long|vector)\b/g,'<span class="kw">$1</span>')}).join('\n')}
function questionPage(id){const q=byId.get(id);if(!q){$('#main').innerHTML='<div class="wrap section"><h1>Question not found.</h1><a href="#questions">Return to the sheet</a></div>';return}const s=(globalThis.SOLUTIONS??{})[q.name],t=TOPICS[q.ti],exact=exactLabs[q.name],lab=exact??t.lab;document.title=`${q.name} — DSA in Motion`;$('#main').innerHTML=`<div class="study">${sidebar(q.ti)}<article class="lesson"><div class="breadcrumbs"><a href="#questions">Question sheet</a> / <a href="#topic/${q.ti}">${t.title}</a> / ${q.qi+1}</div><span class="difficulty ${q.level}">${q.level}</span><h1>${esc(q.name)}</h1>${s?.statement?`<p class="lead">${esc(s.statement)}</p>`:''}<div class="practice-actions"><button id="understood" class="${progress[id]?'done':''}">${progress[id]?'✓ Understood':'Mark understood'}</button><button id="bookmark-question">${bookmarks[id]?'★ Bookmarked':'☆ Bookmark'}</button><a class="textlink" href="${esc(q.leetcode)}" target="_blank" rel="noopener">Open source problem ↗</a></div>${s?`<h2>The idea</h2><p>${esc(s.idea)}</p>${s.example?`<div class="insight"><b>Example</b>${esc(s.example)}</div>`:''}<h2>Work through the solution</h2><ol>${s.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="complexities"><span>Time <b>${esc(s.time)}</b></span><span>Extra space <b>${esc(s.space)}</b></span></div>`:'<p class="empty">Solution content could not load. Reload the page to try again.</p>'}<h2>${exact?'Watch the algorithm':'Explore the topic’s pattern'}</h2><p>${exact?'Change the input and follow each step.':'This is a related concept lab for '+esc(t.title.toLowerCase())+'. It illustrates the pattern; the exact question’s implementation is below.'}</p><div class="lab" id="question-lab"></div>${s?`<h2>The implementation</h2><p>Switch languages to compare the same approach. Copy the function into your practice environment.</p>${/Linked List|Binary Tree|Binary Search Tree|Graphs/.test(t.title)?'<p><small>ListNode, TreeNode, and graph Node types follow the standard judge definitions where referenced. C++ snippets use the standard library; include the relevant headers and using namespace std. Python annotations use the usual typing imports.</small></p>':''}${q.name==='Second Largest'?'<div class="insight"><b>Source-link discrepancy</b>The sheet names an array question but links to “Second Largest Digit in a String”. This solution follows the linked problem and finds the second-largest distinct digit in an alphanumeric string. The row title alone is ambiguous.</div>':''}<div class="codebox"><div class="codebar"><div class="language-tabs">${[['cpp','C++'],['js','JavaScript'],['python','Python']].map(([k,v])=>`<button data-lang="${k}" class="${k===lang?'active':''}">${v}</button>`).join('')}</div><button class="copy" id="copy-code">Copy code</button></div><pre><code id="solution-code">${codeMarkup(s[lang])}</code></pre></div>`:''}<h2>Your notes</h2><p>Write the clue you want to recognize next time. Saved only on this browser.</p><textarea class="notes" aria-label="Personal notes" placeholder="What made this problem click?">${esc(notes[id]??'')}</textarea><div class="source-panel" style="margin-top:30px">Listed in the <a href="https://namastedev.com/namaste-dsa-sheet" target="_blank" rel="noopener">Namaste DSA Sheet ↗</a>. <a href="${esc(q.blog)}" target="_blank" rel="noopener">Source editorial ↗</a> · <a href="${esc(q.video)}" target="_blank" rel="noopener">Source video ↗</a><br>Companies listed by the source: ${q.companies.map(esc).join(', ')}. Independent educational companion; not an official question bank.</div><div class="end-nav"><a href="#topic/${q.ti}">← ${t.title}</a>${questions[questions.indexOf(q)+1]?`<a href="#question/${questions[questions.indexOf(q)+1].id}">Next question →</a>`:'<a href="#questions">Back to sheet →</a>'}</div></article></div>`;labs.push(new AlgorithmLab($('#question-lab'),lab));$('#understood').onclick=()=>{progress[id]=!progress[id];save('dsa-motion-progress',progress);$('#understood').textContent=progress[id]?'✓ Understood':'Mark understood';$('#understood').classList.toggle('done',progress[id]);toast(progress[id]?'Marked understood':'Marked incomplete')};$('#bookmark-question').onclick=()=>{bookmarks[id]=!bookmarks[id];save('dsa-motion-bookmarks',bookmarks);$('#bookmark-question').textContent=bookmarks[id]?'★ Bookmarked':'☆ Bookmark'};$('.notes').oninput=e=>{notes[id]=e.target.value;save('dsa-motion-notes',notes)};document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;document.querySelectorAll('[data-lang]').forEach(x=>x.classList.toggle('active',x===b));$('#solution-code').innerHTML=codeMarkup(s[lang])});$('#copy-code')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(s[lang]);toast('Code copied')}catch{toast('Select the code and copy it with your keyboard.')}})}
function playground(){document.title='Playground — DSA in Motion';$('#main').innerHTML=`<div class="wrap"><div class="page-title"><div class="eyebrow">The pattern playground</div><h1>Change a number.<br>Watch the answer move.</h1><p>Thirteen small labs for the ideas behind the sheet. Pause, scrub, step backward, and test your own examples. Drag the model to change your viewpoint.</p></div><div class="lab-picker">${Object.entries(LABS).map(([id,x])=>`<button data-lab="${id}">${x.title}</button>`).join('')}</div><p id="playground-description" style="color:var(--muted)"></p><div class="lab" id="playground-lab"></div><div class="cta-band"><p id="playground-topic"></p><a class="btn" href="#questions">Practice the questions ↗</a></div></div>`;function choose(id){labs.forEach(l=>l.destroy());labs=[];labs.push(new AlgorithmLab($('#playground-lab'),id));$('#playground-description').textContent=LABS[id].description;$('#playground-topic').innerHTML=`Understand the invariant in <a class="textlink" href="#topic/${LABS[id].topic}">${topicName(LABS[id].topic)} ↗</a>`;document.querySelectorAll('[data-lab]').forEach(b=>b.classList.toggle('active',b.dataset.lab===id))}document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>choose(b.dataset.lab));choose('water')}
function route(){labs.forEach(l=>l.destroy());labs=[];const [page,arg]=(location.hash.slice(1)||'home').split('/');$('nav').classList.remove('open');document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash===`#${page}`||(page==='topic'&&a.hash==='#learn')));if(page==='home')home();else if(page==='learn')learn();else if(page==='questions')renderSheet();else if(page==='topic')topicPage(+arg);else if(page==='question')questionPage(arg);else if(page==='lab')playground();else learn();scrollTo({top:0,behavior:'instant'})}
if(read('dsa-motion-light',false))document.body.classList.add('light');$('#theme').onclick=()=>{document.body.classList.toggle('light');save('dsa-motion-light',document.body.classList.contains('light'));$('#theme').setAttribute('aria-label',`Toggle ${document.body.classList.contains('light')?'dark':'light'} theme`)};$('#mobile-menu').onclick=()=>$('nav').classList.toggle('open');addEventListener('hashchange',route);addEventListener('pagehide',()=>labs.forEach(l=>l.destroy()));route();
})();
